import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileAccess {
    public void readFile(String filename) {
        String baseDir = "/safe/directory/";

        // Construct the path using Paths.get() to handle separators safely
        Path basePath = Paths.get(baseDir);
        Path requestedPath = Paths.get(filename);

        // Resolve the full path and normalize it to prevent directory traversal attacks
        Path resolvedPath = basePath.resolve(requestedPath).normalize();

        // Ensure the resolved path is still within the intended base directory
        if (!resolvedPath.startsWith(basePath)) {
            throw new SecurityException("Attempt to access file outside allowed directory");
        }

        File file = resolvedPath.toFile();
        if (file.exists()) {
            System.out.println("Reading secure file: " + file.getAbsolutePath());
        }
    }
}
